  "mode.salariedDesc": "ᱵᱮᱛᱚᱱ, () => {\n      ᱠᱚᱱᱥᱴ ᱟᱭᱤ ᱰᱤ ᱮᱠᱥ = ᱴᱚᱠᱮᱱᱥ᱾ ᱯᱩᱥ (ᱧᱩᱱᱩᱢ) - ᱑;\n      ᱨᱩᱣᱟᱹᱲ __ᱴᱤ${ᱟᱭᱤᱰᱮᱠᱥ}__`;\n    }s, ᱟᱨ ᱥᱟᱵᱽᱥᱠᱨᱤᱯᱥᱚᱱ — ᱮᱠᱞᱟ ᱵᱟᱝᱠᱷᱟᱱ ᱜᱷᱟᱨᱚᱧᱡᱽ ᱚᱲᱟᱜ ᱾",
