  "guide.setup.subtitle": "ᱫᱚᱦᱲᱟ ᱧᱮᱞ ᱢᱮ ᱟᱢ ᱪᱮᱫ ᱞᱮᱠᱟᱢ ᱵᱮᱵᱷᱟᱨ ᱮᱫᱟ () => {\n      ᱠᱚᱱᱥᱴ ᱟᱭᱤ ᱰᱤ ᱮᱠᱥ = ᱴᱚᱠᱮᱱᱥ᱾ ᱯᱩᱥ (ᱧᱩᱱᱩᱢ) - ᱑;\n      ᱨᱩᱣᱟᱹᱲ __ᱴᱤ${ᱟᱭᱤᱰᱮᱠᱥ}__`;\n    } (ᱵᱷᱮᱛᱟᱱ ᱵᱟᱝᱠᱷᱟᱱ ᱚᱲᱟᱜ ᱦᱚᱲ) ᱟᱨ ᱟᱹᱨᱟᱹᱭ ᱨᱮᱭᱟᱜ ᱢᱩᱲᱩᱫ ᱠᱚ ᱟᱯᱰᱮᱴ ᱢᱮ ᱾ ᱟᱢᱟᱜ ᱵᱤᱞ ᱫᱚ ᱚᱱᱠᱟ ᱜᱮ ᱛᱟᱦᱮᱱᱟ᱾",
  "guide.reviewSetup": "ᱥᱮᱴᱟᱯ ᱧᱮᱞ ᱫᱚᱦᱲᱟ",
  "guide.completedNote": "ᱱᱚᱣᱟ ᱥᱟᱫᱷᱚᱱ ᱨᱮ ᱢᱩᱪᱟᱹᱫ ᱜᱟᱭᱤᱰ ᱫᱚ ᱯᱩᱨᱟᱹᱣ ᱞᱮᱱᱟ ᱾ ᱫᱚᱦᱲᱟ ᱧᱮᱞ ᱞᱟᱹᱜᱤᱫ ᱪᱮᱛᱟᱱ ᱨᱮ ᱞᱤᱱ ᱢᱮ ᱾",
  "guide.pulse.label": "ᱱᱳᱭᱟ ᱫᱚ ᱪᱮᱫ ᱠᱟᱱᱟ?",
  "guide.pulse.pressureTitle": "ᱯᱨᱮᱥᱟᱨ ᱥᱠᱚᱨ",
  "guide.pulse.pressureText": "ᱟᱢᱟᱜ ᱠᱟᱹᱣᱰᱤ ᱪᱷᱟᱯ ᱥᱠᱚᱨ (᱐-᱑᱐᱐) ᱫᱚ ᱟᱢᱟᱜ ᱠᱟᱹᱣᱰᱤ ᱨᱮᱭᱟᱜ ᱛᱤᱱᱟᱹᱜ ᱜᱟᱱ ᱴᱷᱟᱹᱣᱠᱟᱹ ᱫᱟᱭᱤᱠ ᱠᱚ ᱞᱟᱹᱜᱤᱫ ᱪᱟᱞᱟᱜ ᱠᱟᱱᱟ ᱚᱱᱟᱭ ᱡᱚᱠᱷᱟᱭᱟ ᱾ ᱔᱕ ᱠᱷᱚᱱ ᱞᱟᱛᱟᱨ ᱫᱚ ᱦᱚᱲᱢᱚ ᱜᱮᱭᱟ ᱾ ᱗᱐ ᱠᱷᱚᱱ ᱪᱮᱛᱟᱱ ᱢᱮᱱᱫᱚ ᱟᱢᱟᱜ ᱫᱟᱭᱤᱠ ᱠᱚ ᱦᱟᱢᱟᱞ ᱜᱮᱭᱟ ᱾",
  "guide.pulse.freeCashTitle": "Free ᱴᱟᱠᱟ",
  "guide.pulse.freeCashText": "ᱱᱤᱭᱟᱹ ᱪᱟᱸᱫᱚ ᱟᱢᱟᱜ ᱯᱮᱭᱢᱮᱱᱴ ᱯᱮᱭᱢᱮᱱᱴ ᱛᱟᱭᱚᱢ ᱴᱟᱠᱟ ᱵᱟᱹᱠᱤ ᱢᱮᱱᱟᱜᱼᱟ ᱾ ᱱᱚᱶᱟ ᱜᱮ ᱟᱢ ᱥᱟᱹᱨᱤ ᱛᱮ ᱠᱷᱚᱨᱪᱟ, ᱵᱟᱧᱪᱟᱣ, ᱥᱮ ᱞᱟᱜᱽᱱᱟ ᱦᱩᱭᱩᱜ ᱛᱟᱢᱟ᱾",
  "guide.pulse.survivalTitle": "ᱡᱤᱣᱤᱫ ᱛᱟᱦᱮᱱ ᱨᱟᱱᱣᱮ",
  "guide.pulse.survivalText": "ᱡᱩᱫᱤ ᱟᱢ ᱛᱮᱦᱮᱧ ᱥᱟᱱᱟᱢ ᱠᱟᱢᱟᱣ ᱟᱫ ᱠᱮᱫᱟᱢ, ᱛᱤᱱᱟᱹᱜ ᱪᱟᱸᱫᱚ ᱵᱟᱧᱪᱟᱣ ᱠᱷᱚᱱ ᱟᱢᱟᱜ ᱫᱟᱭᱤᱠ ᱠᱚ ᱮᱢ ᱯᱩᱨᱟᱹᱣ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ? ᱖+ ᱪᱟᱸᱫᱚ ᱫᱚ ᱡᱚᱥ ᱠᱟᱱᱟ ᱾",
  "support.title": "ᱜᱚᱲᱚ ᱟᱨ ᱜᱚᱲᱚ",
  "support.subtitle": "ᱫᱤᱥᱟᱹ, ᱯᱨᱟᱭᱣᱮᱥᱤ, ᱟᱨ ᱟᱞᱮ ᱴᱷᱮᱱ ᱥᱮᱴᱮᱨᱚᱜ ᱨᱮᱭᱟᱜ ᱦᱚᱨ ᱠᱚ ᱾",
