  "support.helpCenterHint": "ᱚᱲᱟᱜ, ᱯᱟᱹᱞᱥ ᱟᱨ ᱵᱤᱞ ᱵᱚᱞᱚᱱ ᱨᱮᱭᱟᱜ ᱣᱟᱠᱛᱷᱨᱩ ᱫᱚᱦᱲᱟ ᱪᱟᱹᱞᱩᱭ ᱢᱮ ᱾",
