  "support.about": "ᱵᱟᱨᱮᱛᱮ () => {\n      ᱠᱚᱱᱥᱴ ᱟᱭᱤ ᱰᱤ ᱮᱠᱥ = ᱴᱚᱠᱮᱱᱥ᱾ ᱯᱩᱥ (ᱧᱩᱱᱩᱢ) - ᱑;\n      ᱨᱩᱣᱟᱹᱲ __ᱴᱤ${ᱟᱭᱤᱰᱮᱠᱥ}__`;\n    }",
  "support.aboutBody": "Perovo ᱵᱷᱟᱨᱚᱱ ᱚᱲᱟᱜ ᱠᱚ ᱵᱤᱞ, ᱨᱤᱱ ᱮᱢ ᱟᱨ ᱪᱟᱸᱫᱚ ᱪᱷᱟᱯ ᱴᱨᱟᱠ ᱞᱟᱹᱜᱤᱫ ᱜᱚᱲᱚ ᱮᱢᱟ ᱠᱚᱣᱟᱭ ᱾ Perovo ᱦᱚᱛᱮᱛᱮ ᱛᱮᱭᱟᱨ ᱟᱠᱟᱱᱟ, Perovo ᱞᱟᱛᱟᱨ ᱨᱮ ᱢᱤᱫ SaaS ᱠᱚᱢᱯᱟᱱᱤ ᱾",
