  "notifications.enabledOkNative": "ᱱᱚᱴᱤᱯᱷᱤᱠᱮᱥᱚᱱ ᱠᱚ ᱪᱟᱹᱞᱩ ᱮᱱᱟ ᱾ ᱵᱟᱹᱠᱛᱤ ᱟᱨ ᱵᱟᱹᱠᱛᱤ ᱵᱤᱞ ᱠᱚ ᱟᱢ ᱱᱚᱣᱟ ᱥᱟᱫᱷᱚᱱ ᱨᱮ ᱮᱞᱟᱨᱴ ᱢᱮᱭᱟᱭ ᱾",
  "notifications.deniedErrNative": "Android ᱥᱮᱴᱤᱝ ᱨᱮ ᱵᱞᱚᱠ ᱟᱠᱟᱱᱟ ᱾ ᱥᱮᱴᱤᱝ ᱡᱷᱤᱡᱽ ᱢᱮ → ᱮᱯᱥ → ᱯᱮᱨᱚᱵᱷᱚ → ᱱᱚᱴᱤᱯᱷᱤᱠᱮᱥᱚᱱ ᱟᱨ ᱮᱞᱟᱨᱴ ᱨᱮᱭᱟᱜ ᱟᱱᱩᱢᱟᱛ ᱢᱮ, ᱚᱱᱟ ᱛᱟᱭᱚᱢ ᱫᱚᱦᱲᱟ ᱪᱮᱥᱴᱟᱭ ᱢᱮ ᱾",
  "notifications.testDeniedNative": "ᱟᱹᱭᱫᱟᱹᱨ ᱵᱟᱝ ᱦᱩᱭ ᱟᱠᱟᱱᱟ᱾ Android ᱥᱮᱴᱤᱝ ᱨᱮ ᱱᱚᱴᱤᱯᱷᱤᱠᱮᱥᱚᱱ ᱨᱮᱭᱟᱜ ᱪᱷᱟᱹᱲ ᱮᱢᱚᱜ ᱢᱮ, ᱚᱱᱟ ᱛᱟᱭᱚᱢ ᱫᱚᱦᱲᱟ ᱠᱩᱨᱩᱢᱩᱴᱩᱭ ᱢᱮ ᱾",
  "notifications.nativeHint": "ᱴᱨᱮ ᱮᱞᱟᱨᱴ ᱠᱚ ᱵᱮᱵᱷᱟᱨ ᱮᱫᱟ Android ᱱᱚᱴᱤᱯᱷᱤᱠᱮᱥᱚᱱ ᱠᱚ ᱾ ᱱᱚᱣᱟ ᱥᱠᱨᱤᱱ ᱨᱮ ᱵᱤᱞ ᱫᱤᱥᱟᱹ ᱪᱟᱹᱞᱩ ᱫᱚᱦᱚ ᱠᱟᱜ ᱢᱮ᱾ ᱮᱯ ᱵᱚᱱᱫᱚ ᱠᱟᱛᱮ ᱦᱚᱸ ᱵᱟᱹᱠᱛᱤ ᱟᱨ ᱵᱟᱹᱠᱛᱤ ᱵᱤᱞ ᱠᱚ ᱵᱟᱰᱟᱭ ᱚᱪᱚᱭᱟ ᱾",
  "notifications.deniedErr": "ᱵᱽᱨᱟᱣᱩᱡᱟᱨ ᱥᱮᱴᱤᱝ ᱨᱮ ᱵᱞᱚᱠ ᱟᱠᱟᱱᱟ ᱾ ᱱᱚᱶᱟ ᱥᱟᱭᱤᱴ ᱞᱟᱹᱜᱤᱫ ᱱᱚᱴᱤᱯᱷᱤᱠᱮᱥᱚᱱ ᱨᱮᱭᱟᱜ ᱫᱟᱣ ᱮᱢᱚᱜ ᱢᱮ, ᱚᱱᱟ ᱛᱟᱭᱚᱢ ᱫᱚᱦᱲᱟ ᱠᱩᱨᱩᱢᱩᱴᱩᱭ ᱢᱮ ᱾",
  "notifications.testOk": "ᱟᱢᱟᱜ ᱥᱤᱥᱴᱚᱢ ᱱᱚᱴᱤᱯᱷᱤᱠᱮᱥᱚᱱ ᱯᱮᱱᱮᱞ ᱟᱨ ᱤᱱ-ᱮᱯ ᱵᱮᱞ ᱨᱮ ᱵᱷᱮᱡᱟ ᱟᱠᱟᱱᱟ ᱾ ᱱᱚᱣᱟ ᱧᱮᱞ ᱞᱟᱹᱜᱤᱫ ᱯᱷᱚᱱ ᱨᱮ ᱞᱟᱛᱟᱨ ᱥᱣᱟᱭᱤᱯ ᱢᱮ᱾",
