  "tools.logSpend.smsPlaceholder": "ᱢᱟᱲᱟᱝ ᱯᱮᱨᱮᱡ ᱞᱟᱹᱜᱤᱫ ᱵᱮᱝᱠ ᱰᱮᱵᱤᱴ ᱞᱟᱴᱷᱟᱭ ᱢᱮ SMS",
