  "stability.goalBalance.tensions": "ᱱᱤᱛᱚᱜ ᱠᱟᱹᱣᱰᱤ ᱫᱚ ᱥᱟᱯᱚᱨᱴ ᱞᱟᱹᱜᱤᱫ ᱞᱟᱹᱲᱦᱟᱹᱭ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ {tensions} ᱢᱤᱫ ᱚᱠᱛᱚ ᱨᱮ ᱾",
