  "insight.goal-overlap": "ᱟᱢ ᱫᱚ {count} ᱡᱚᱥ ᱠᱚᱢ ᱴᱨᱮᱠ ᱮᱫᱟ ᱛᱤᱱ ᱨᱮ ᱪᱟᱸᱫᱚ ᱵᱟᱹᱠᱛᱤ ᱫᱚ ᱟᱹᱭᱫᱟᱹᱨ ᱨᱮᱭᱟᱜ ᱢᱟᱨᱟᱝ ᱦᱟᱹᱴᱤᱧ ᱮ ᱵᱮᱵᱷᱟᱨᱟ — ᱞᱟᱦᱟᱱᱛᱤ ᱫᱚ ᱥᱟᱱᱟᱢ ᱢᱩᱲᱩᱫ ᱨᱮ ᱵᱟᱹᱭ ᱵᱟᱹᱭ ᱛᱮ ᱦᱩᱭ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾",
  "insight.goal-edu-wedding": "ᱥᱮᱪᱮᱫ ᱟᱨ ᱵᱟᱯᱞᱟ ᱥᱮ ᱠᱟᱹᱢᱤᱦᱚᱨᱟ ᱨᱮᱭᱟᱜ ᱡᱚᱥ ᱢᱤᱫ ᱥᱟᱶᱛᱮ ᱢᱤᱫ ᱯᱩᱥᱴᱟᱹᱣ ᱪᱟᱸᱫᱚ ᱥᱞᱟᱭᱤᱥ ᱞᱟᱹᱠᱛᱤᱭᱟ — ᱵᱤᱪᱟᱹᱨ ᱢᱮ ᱚᱠᱟ ᱫᱚ ᱢᱟᱲᱟᱝ ᱨᱮ ᱦᱤᱡᱩᱜᱼᱟ᱾",
