  "wealthDetail.property.holdModerateDetail": "ᱧᱩᱛᱩᱢ ᱩᱛᱷᱱᱟᱹᱣ ᱫᱚ ᱢᱩᱲᱩᱫ ᱵᱩᱱᱤᱭᱟᱫᱷ ᱨᱮ ᱢᱩᱫᱽᱨᱟ ᱫᱚ ᱦᱟᱨᱟᱣ ᱮᱫᱟᱭ, ᱢᱮᱱᱠᱷᱟᱱ ᱥᱟᱹᱨᱤ ᱨᱚᱲ ᱫᱚ ᱢᱚᱴᱟᱨᱮᱴ ᱜᱮᱭᱟ᱾ ᱥᱟᱵ ᱢᱮ ᱡᱩᱫᱤ ᱟᱢ ᱞᱤᱠᱩᱰᱤᱴᱤ ᱵᱟᱝ ᱞᱟᱹᱠᱛᱤᱭᱟᱢᱟ; ᱟᱠᱨᱤᱧ ᱫᱚ ᱥᱩᱢᱩᱝ ᱢᱤᱫ ᱠᱮᱴᱮᱡ ᱫᱚᱦᱲᱟ ᱞᱟᱜᱽᱱᱟ ᱯᱚᱱᱛᱷᱟ ᱥᱮ ᱡᱤᱭᱚᱱ ᱜᱷᱚᱴᱚᱱ ᱴᱟᱠᱟ ᱞᱟᱹᱠᱛᱤ ᱞᱟᱹᱜᱤᱫ ᱢᱮᱱᱮᱛ ᱢᱮᱱᱟᱜᱼᱟ ᱾",
  "wealthDetail.property.holdMature": "ᱢᱮᱪᱭᱚᱨ ᱦᱚᱞᱰ — ᱠᱷᱟᱹᱛᱤᱨ ᱫᱚᱠᱟᱱ, ᱩᱥᱟᱹᱨᱟ ᱴᱟᱠᱟ ᱫᱚ ᱵᱟᱝ",
  "wealthDetail.property.holdMatureDetail": "You have held long enough to ride multiple cycles. Real returns are positive but modest — this asset works as generational wealth and inflation hedge. Avoid selling unless relocation, debt payoff, or diversification clearly wins after tax and brokerage.",
  "wealthDetail.property.realReturnNote": "Assumes ~{inflation}% annual inflation (India long-run average).",
  "wealthDetail.property.deepAnalysis": "ᱦᱚᱞᱰ ᱟᱨ ᱵᱟᱡᱟᱨ ᱵᱤᱥᱲᱤ",
  "wealthDetail.property.yearsToTarget": "ᱱᱤᱛᱚᱜ ᱞᱚᱜᱚᱱ ᱛᱮ, ~{years} ᱟᱨᱦᱚᱸ ᱥᱮᱨᱢᱟ ᱑᱒% CAGR ᱡᱚᱥ ᱥᱮᱴᱮᱨᱚᱜ ᱞᱟᱹᱜᱤᱫ ᱾",
  "wealthDetail.property.outlookMetro": "Metro corridors: infra (metro lines, IT parks) often lifts land values — watch local RERA/project news.",
  "wealthDetail.property.outlookTier2": "Tier-2 cities: industrial corridors and highway links can accelerate appreciation in 5–8 year cycles.",
  "wealthDetail.property.outlookTier3": "Smaller towns: liquidity is lower — favour long holds and verify title before major price revisions.",
  "wealthDetail.property.outlookAreaFallback": "ᱟᱢᱟᱜ ᱴᱚᱴᱷᱟ",
  "wealthDetail.property.purchaseThen": "Purchase price (then)",
  "wealthDetail.property.inflationCostToday": "ᱢᱩᱫᱽᱨᱟ-ᱵᱮᱵᱷᱟᱨ ᱜᱚᱱᱚᱝ (ᱛᱮᱦᱮᱧ)",
  "wealthDetail.property.inflationCostHint": "ᱟᱢᱟᱜ ᱱᱤᱛᱚᱜ ᱜᱚᱱᱚᱝ ᱫᱚ ᱵᱟᱝ ᱠᱟᱱᱟ - ᱛᱮᱦᱮᱧᱟᱜ ᱴᱟᱠᱟ ᱨᱮ ᱟᱥᱚᱞ ᱠᱤᱨᱤᱧ ᱨᱮᱭᱟᱜ ᱜᱚᱱᱚᱝ ᱪᱮᱫ ᱠᱟᱱᱟ ᱾",
  "wealthDetail.property.narrative.inflationAdjustedCost": "Your ₹{purchase} purchase equals roughly ₹{todayEquivalent} in today's money after {years} years at ~{inflation}% compounded inflation — real growth is measured against that, not the original price alone.",
  "wealthDetail.property.narrative.purchaseDerived": "ᱠᱤᱨᱤᱧ ᱫᱟᱢ ᱫᱚ ᱟᱢ ᱮᱢ ᱟᱠᱟᱫ ᱫᱚᱨ × ᱴᱚᱴᱷᱟ ᱠᱷᱚᱱ ᱦᱤᱡᱩᱜ ᱠᱟᱱᱟ — ᱡᱩᱫᱤ ᱢᱩᱴ ᱵᱷᱩᱞ ᱧᱮᱞᱚᱜ ᱠᱷᱟᱱ ᱥᱟᱥᱟᱯᱲᱟᱣ ᱨᱮ ᱞᱤᱱ ᱢᱮ ᱾",
  "wealthDetail.property.narrative.realReturnExplain": "Nominal CAGR {cagr}% minus ~{inflation}% inflation ≈ {real}% real return per year — property often looks strong in rupee terms while barely beating inflation after costs.",
  "wealthDetail.property.narrative.vsBenchmarkExplain": "Your {cagr}% CAGR vs ~{benchmark}% typical for this city tier ({delta}% difference) — use as a rough peer check, not a buy/sell signal.",
  "wealthDetail.property.narrative.longHoldLiquidity": "ᱞᱚᱝᱜᱽ ᱦᱚᱞ ᱫᱚ ᱚᱠᱛᱚ ᱡᱷᱩᱠᱤ ᱠᱚᱢᱟᱭ ᱢᱮᱱᱠᱷᱟᱱ ᱯᱩᱭᱥᱟᱹ ᱫᱚ ᱞᱚᱠ ᱜᱮᱭᱟ — ᱱᱚᱶᱟ ᱟᱠᱷᱨᱤᱧ ᱥᱚᱢᱯᱚᱛᱛᱤ ᱞᱮᱠᱟ ᱵᱮᱵᱚᱦᱟᱨ ᱞᱟᱦᱟᱨᱮ ᱖-᱑᱒ ᱪᱟᱸᱫᱚ ᱠᱷᱚᱨᱪᱟ ᱮᱴᱟᱜ ᱡᱟᱭᱜᱟ ᱨᱮ ᱫᱚᱦᱚ ᱠᱟᱜ ᱢᱮ᱾",
  "wealthDetail.property.narrative.rentYieldExplain": "Estimated gross rent yield ~{yield}% — compare with FD/PPF after tax; if you live in the property, treat rent savings as implicit yield.",
  "wealthDetail.property.narrative.rentVsIncome": "ᱡᱩᱫᱤ ᱯᱩᱨᱟᱹ ᱵᱷᱟᱲᱟ ᱢᱮᱱᱟᱜᱼᱟ, ᱢᱩᱴ ᱵᱷᱟᱲᱟ ᱫᱚ ᱟᱢᱟᱜ ᱪᱟᱸᱫᱚ ᱟᱹᱭᱫᱟᱹᱨ ᱨᱮᱭᱟᱜ ~{pct}% ᱦᱩᱭᱩᱜᱼᱟ — ᱧᱮᱞ ᱢᱮ ᱚᱱᱟ ᱟᱢᱟᱜ ᱥᱟᱹᱨᱤ ᱥᱮ ᱧᱟᱢᱚᱜ ᱵᱷᱟᱲᱟ ᱥᱟᱶ ᱢᱤᱞᱟᱹᱣ ᱜᱮᱭᱟ ᱥᱮ ᱵᱟᱝᱟ᱾",
  "wealthDetail.property.narrative.valueVsIncome": "ᱱᱚᱣᱟ ᱡᱤᱱᱤᱥ ᱫᱚ ~{multiple}× ᱟᱢᱟᱜ ᱥᱮᱨᱢᱟᱠᱤᱭᱟᱹ ᱟᱹᱨᱟᱹᱭ ᱠᱟᱜᱚᱡᱽ ᱨᱮ — ᱢᱟᱨᱟᱝ ᱞᱚᱱᱰᱨᱮᱥᱚᱱ; ᱤᱢᱟᱨᱡᱮᱱᱥᱤ ᱟᱨ ᱰᱟᱭᱵᱷᱚᱨᱥᱤᱯᱷᱤᱠᱮᱥᱚᱱ ᱯᱞᱟᱱᱤᱝ ᱨᱮ ᱯᱷᱮᱠᱴᱚᱨ ᱾",
  "wealthDetail.property.narrative.highValueTier3Liquidity": "ᱠᱟᱹᱴᱤᱡ ᱵᱟᱡᱟᱨ ᱨᱮ ᱱᱚᱶᱟ ᱜᱚᱱᱚᱝ ᱛᱮ, ᱠᱤᱨᱤᱧ ᱦᱚᱲ ᱧᱟᱢ ᱞᱟᱹᱜᱤᱫ ᱪᱟᱸᱫᱚ ᱞᱟᱜᱟᱣ ᱫᱟᱲᱮᱭᱟᱜ-ᱟ - ᱜᱚᱱᱚᱝ ᱫᱚ ᱥᱟᱹᱨᱤ ᱞᱮᱠᱟ ᱟᱨ ᱯᱩᱨᱟᱹ ᱜᱚᱱᱚᱝ ᱫᱚ ᱛᱟᱞᱟ ᱛᱮ ᱧᱟᱢᱚᱜ ᱠᱟᱱ ᱴᱟᱠᱟ ᱞᱮᱠᱟ ᱞᱮᱠᱷᱟ ᱠᱷᱚᱱ ᱥᱟᱦᱟᱜ ᱢᱮ᱾",
  "wealthDetail.property.narrative.highValueTier2Liquidity": "ᱴᱟᱭᱟᱨ-᱒ ᱵᱟᱡᱟᱨ ᱞᱟᱹᱜᱤᱫ ᱪᱮᱛᱟᱱ ᱴᱤᱠᱤᱴ — ᱟᱢᱟᱜ ᱞᱟᱹᱭ ᱜᱚᱱᱚᱝ ᱨᱮ ᱩᱥᱟᱹᱨᱟ ᱞᱤᱠᱩᱰᱤᱴᱤ ᱵᱩᱡᱷᱟᱹᱣ ᱞᱟᱦᱟᱨᱮ ᱥᱩᱨ ᱨᱮ ᱨᱮᱡᱤᱥᱴᱟᱨ ᱟᱠᱟᱱ ᱟᱹᱠᱷᱨᱤᱧ ᱠᱚ ᱯᱩᱥᱴᱟᱹᱣ ᱢᱮ᱾",
  "wealthDetail.property.narrative.targetCagrReality": "ᱱᱚᱸᱰᱮ ᱠᱷᱚᱱ 12% CAGR ᱯᱟᱧᱡᱟ ᱞᱟᱹᱜᱤᱫ ᱛᱮᱦᱮᱧᱟᱜ ᱞᱮᱠᱟ ᱛᱮ ~{years} ᱟᱨᱦᱚᱸ ᱥᱮᱨᱢᱟ ᱞᱟᱜᱟᱜᱼᱟ — ᱟᱢᱟᱜ ᱦᱚᱞᱰᱤᱝ ᱫᱚ ᱞᱟᱦᱟ ᱠᱷᱚᱱ ᱜᱮ ᱠᱮᱴᱮᱡ ᱧᱩᱛᱩᱢ ᱞᱟᱵᱷ ᱮ ᱮᱢ ᱟᱠᱟᱫᱟ; ᱟᱜᱟᱢ ᱨᱮᱭᱟᱜ ᱨᱩᱣᱟᱹᱲ ᱥᱟᱫᱷᱟᱨᱚᱱ ᱦᱩᱭ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾",
  "wealthDetail.property.narrative.landHold": "ᱡᱟᱭᱜᱟ: ᱠᱚᱢ ᱧᱮᱞ ᱡᱚᱛᱚᱱ ᱢᱮᱱᱠᱷᱟᱱ ᱵᱟᱹᱭ ᱵᱟᱹᱭ ᱛᱮ ᱞᱤᱠᱩᱰᱤᱴᱤ — ᱑᱐+ ᱥᱮᱨᱢᱟ ᱫᱤᱱᱟᱹᱢ ᱞᱟᱹᱜᱤᱫ ᱥᱚᱨᱮᱥ; ᱥᱩᱪᱤ ᱞᱟᱦᱟᱨᱮ ᱮᱱᱠᱩᱢᱵᱚᱨᱮᱱᱥ, ᱡᱚᱱᱤᱝ, ᱟᱨ ᱥᱚᱸᱡᱷᱮ ᱯᱟᱥᱱᱟᱣ ᱨᱮᱭᱟᱜ ᱱᱚᱴᱤᱯᱷᱤᱠᱮᱥᱚᱱ ᱧᱮᱞ ᱢᱮ᱾",
  "wealthDetail.property.narrative.commercialHold": "ᱵᱮᱯᱟᱨᱤ: ᱠᱷᱟᱹᱞᱤ ᱴᱷᱟᱶ ᱟᱨ ᱵᱷᱟᱲᱟᱭᱤᱡ ᱜᱩᱱ ᱫᱚ ᱴᱷᱟᱶ ᱞᱮᱠᱟ ᱜᱮ ᱢᱮᱱᱟᱜᱼᱟ - ᱯᱷᱩᱴᱯᱷᱚᱞ ᱥᱮ ᱵᱷᱟᱲᱟ ᱨᱮᱭᱟᱜ ᱥᱟᱨᱛ ᱠᱚᱢᱡᱩᱨᱚᱜ ᱠᱷᱟᱱ ᱫᱚᱦᱲᱟ ᱢᱩᱞᱤᱱ ᱢᱮ᱾",
  "wealthDetail.property.narrative.residentialHold": "ᱟᱵᱟᱥᱤᱭᱟᱹ: ᱱᱤᱡᱮᱨ ᱵᱮᱵᱷᱟᱨ ᱛᱮ ᱟᱠᱨᱤᱧ ᱨᱮᱭᱟᱜ ᱪᱷᱟᱯ ᱠᱚᱢᱚᱜᱼᱟ; ᱡᱩᱫᱤ ᱵᱷᱟᱲᱟ ᱮᱢ ᱠᱷᱟᱱ, ᱵᱷᱟᱲᱟᱴᱤᱭᱟᱹ ᱠᱚᱣᱟᱜ ᱟᱹᱪᱩᱨ ᱟᱨ ᱥᱟᱶᱛᱟ ᱧᱮᱞ ᱡᱚᱛᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱴᱨᱮᱠ ᱢᱮ ᱾",
  "wealthDetail.property.narrative.verifyTitle": "ᱡᱟᱦᱟᱱ ᱟᱹᱠᱷᱨᱤᱧ ᱞᱟᱦᱟᱨᱮ: ᱮᱱᱠᱩᱢᱵᱽᱨᱮᱱᱥ ᱥᱟᱨᱴᱤᱯᱷᱤᱠᱮᱴ, ᱥᱚᱢᱯᱚᱛᱛᱤ ᱴᱮᱠᱥ ᱨᱟᱹᱥᱤᱫ, ᱟᱨ ᱢᱭᱩᱴᱮᱥᱚᱱ ᱥᱛᱤᱛᱤ — ᱱᱚᱸᱰᱮ ᱵᱤᱞᱚᱢ ᱠᱟᱜᱚᱡᱽ ᱞᱟᱵᱷ ᱠᱚ ᱢᱤᱴᱟᱣᱟ᱾",
