  "wealthDetail.fd.debtMfNote": "ᱨᱤᱱ ᱢᱩᱴᱷᱟᱹᱱ ᱯᱷᱟᱱᱰ (ᱡᱮᱞᱠᱟ ᱠᱟᱹᱴᱤᱡ ᱚᱠᱛᱚ ᱥᱮ ᱠᱚᱨᱯᱚᱨᱴ ᱵᱚᱱᱰ ᱯᱷᱟᱱᱰ) ᱫᱚ ᱱᱚᱝᱠᱟᱱ ᱨᱤᱴᱟᱨ ᱮᱢ ᱮᱫᱟ ᱢᱮᱱᱠᱷᱟᱱ ᱯᱷᱩᱨᱜᱟᱹᱞ ᱨᱮ ᱟᱢᱟᱜ ᱥᱞᱟᱵ ᱫᱚᱨ ᱨᱮ ᱴᱮᱠᱥ ᱮᱢ ᱠᱟᱱᱟ — FD ᱞᱮᱠᱟ ᱥᱮᱨᱢᱟᱠᱤᱭᱟᱹ TDS ᱵᱟᱹᱱᱩᱜ-ᱟ᱾ ᱩᱱᱠᱩ ᱫᱚ ᱱᱟᱯᱟᱭ ᱞᱤᱠᱩᱰᱤᱴᱤ ᱦᱚᱸ ᱠᱚ ᱮᱢᱚᱜ ᱠᱟᱱᱟ (ᱴᱤ+᱑ ᱨᱤᱰᱮᱢᱯᱥᱚᱱ ᱵᱚᱱᱟᱢ ᱮᱯᱷ ᱰᱤ ᱚᱠᱛᱚ ᱢᱟᱲᱟᱝ ᱚᱰᱚᱠ ᱯᱮᱱᱟᱞᱴᱤ)᱾",
